"""SO(3) rotations generated by scalar-first unit quaternions.

Convention
----------
Quaternion: q = (w, x, y, z), scalar first.
Active rotation of column vectors:
    p_rotated = q * p * q^{-1}

The rotation matrix satisfies:
    p_rotated = R(q) @ p

The map is invariant under q -> -q.
"""

from __future__ import annotations

import math
from typing import Iterable

import numpy as np
from numpy.typing import NDArray

try:
    from .quaternions import Quaternion, DEFAULT_TOLERANCE
except ImportError:
    from quaternions import Quaternion, DEFAULT_TOLERANCE


FloatArray = NDArray[np.float64]


def _vector3(vector: Iterable[float]) -> FloatArray:
    """Convert an iterable into a finite three-dimensional vector."""
    result = np.asarray(tuple(vector), dtype=float)
    if result.shape != (3,):
        raise ValueError("Expected a three-dimensional vector.")
    if not np.all(np.isfinite(result)):
        raise ValueError("Vector components must be finite.")
    return result


def _unit_quaternion(q: Quaternion) -> Quaternion:
    """Normalize q and reject invalid input types."""
    if not isinstance(q, Quaternion):
        raise TypeError("Expected a Quaternion instance.")
    return q.normalized()


def quaternion_to_matrix(q: Quaternion) -> FloatArray:
    """Return the active SO(3) rotation matrix associated with q.

    The quaternion is normalized internally.

    For q = (w, x, y, z), the matrix is:

        [[1-2(y²+z²), 2(xy-wz),   2(xz+wy)],
         [2(xy+wz),   1-2(x²+z²), 2(yz-wx)],
         [2(xz-wy),   2(yz+wx),   1-2(x²+y²)]]
    """
    q = _unit_quaternion(q)
    w, x, y, z = q.as_tuple()

    return np.array(
        [
            [
                1.0 - 2.0 * (y * y + z * z),
                2.0 * (x * y - w * z),
                2.0 * (x * z + w * y),
            ],
            [
                2.0 * (x * y + w * z),
                1.0 - 2.0 * (x * x + z * z),
                2.0 * (y * z - w * x),
            ],
            [
                2.0 * (x * z - w * y),
                2.0 * (y * z + w * x),
                1.0 - 2.0 * (x * x + y * y),
            ],
        ],
        dtype=float,
    )


def rotate_vector(q: Quaternion, vector: Iterable[float]) -> FloatArray:
    """Rotate a 3D vector using the SO(3) matrix representation."""
    v = _vector3(vector)
    return quaternion_to_matrix(q) @ v


def rotate_vector_quaternion(
    q: Quaternion,
    vector: Iterable[float],
) -> FloatArray:
    """Rotate a vector directly through q * p * q^{-1}."""
    v = _vector3(vector)
    result = q.rotate_pure(v)
    return np.asarray(result.vector, dtype=float)


def axis_angle_to_quaternion(
    axis: Iterable[float],
    angle: float,
) -> Quaternion:
    """Construct a unit quaternion from an axis and angle in radians.

    q = (cos(angle/2), axis_hat * sin(angle/2)).
    """
    axis_array = _vector3(axis)
    if not math.isfinite(angle):
        raise ValueError("Angle must be finite.")

    axis_norm = float(np.linalg.norm(axis_array))
    if axis_norm == 0.0:
        if abs(angle) <= DEFAULT_TOLERANCE:
            return Quaternion.identity()
        raise ValueError("A nonzero angle requires a nonzero axis.")

    axis_hat = axis_array / axis_norm
    half_angle = 0.5 * float(angle)
    sine = math.sin(half_angle)

    return Quaternion(
        math.cos(half_angle),
        *(axis_hat * sine),
    )


def quaternion_to_axis_angle(
    q: Quaternion,
    tolerance: float = DEFAULT_TOLERANCE,
) -> tuple[FloatArray, float]:
    """Return a canonical axis and angle in [0, pi].

    The sign of q is chosen so that its scalar component is non-negative.
    At zero rotation, the returned axis is (1, 0, 0).
    """
    if tolerance < 0:
        raise ValueError("Tolerance must be non-negative.")

    q = _unit_quaternion(q)

    # q and -q represent the same SO(3) rotation.
    if q.w < 0.0:
        q = -q

    w = min(1.0, max(-1.0, q.w))
    vector_part = np.asarray(q.vector, dtype=float)
    sine_half = float(np.linalg.norm(vector_part))

    angle = 2.0 * math.atan2(sine_half, w)

    if sine_half <= tolerance:
        return np.array([1.0, 0.0, 0.0]), 0.0

    axis = vector_part / sine_half
    return axis, angle


def is_rotation_matrix(
    matrix: NDArray[np.float64],
    tolerance: float = 1e-10,
) -> bool:
    """Check R.T @ R = I and det(R) = +1."""
    matrix = np.asarray(matrix, dtype=float)

    if matrix.shape != (3, 3):
        return False
    if not np.all(np.isfinite(matrix)):
        return False
    if tolerance < 0:
        raise ValueError("Tolerance must be non-negative.")

    orthogonality_error = np.linalg.norm(
        matrix.T @ matrix - np.eye(3),
        ord="fro",
    )
    determinant_error = abs(float(np.linalg.det(matrix)) - 1.0)

    return (
        orthogonality_error <= tolerance
        and determinant_error <= tolerance
    )


def rotation_matrix_error(
    matrix: NDArray[np.float64],
) -> dict[str, float]:
    """Return numerical diagnostics for a 3x3 matrix."""
    matrix = np.asarray(matrix, dtype=float)

    if matrix.shape != (3, 3):
        raise ValueError("Expected a 3x3 matrix.")

    return {
        "orthogonality_frobenius": float(
            np.linalg.norm(matrix.T @ matrix - np.eye(3), ord="fro")
        ),
        "determinant": float(np.linalg.det(matrix)),
        "determinant_error": float(
            abs(np.linalg.det(matrix) - 1.0)
        ),
    }


def compose_rotations(
    q1: Quaternion,
    q2: Quaternion,
) -> Quaternion:
    """Return the quaternion for R(q1) @ R(q2).

    The rightmost rotation acts first:
        R(q1 * q2) = R(q1) @ R(q2).
    """
    return (q1.normalized() * q2.normalized()).normalized()


def rotation_distance(
    q1: Quaternion,
    q2: Quaternion,
) -> float:
    """Return the geodesic angular distance in SO(3), in radians.

    The result lies in [0, pi] and is invariant under either lift sign.
    """
    a = q1.normalized()
    b = q2.normalized()

    dot = abs(
        a.w * b.w
        + a.x * b.x
        + a.y * b.y
        + a.z * b.z
    )
    dot = min(1.0, max(0.0, dot))

    return 2.0 * math.acos(dot)


def verify_quaternion_matrix_action(
    q: Quaternion,
    vector: Iterable[float],
) -> float:
    """Return the discrepancy between the two rotation implementations.

    Compares:
        R(q) @ v
    with:
        vector part of q * (0,v) * q^{-1}.
    """
    matrix_result = rotate_vector(q, vector)
    quaternion_result = rotate_vector_quaternion(q, vector)

    return float(np.linalg.norm(matrix_result - quaternion_result))
